function findMissingRanges(nums, lower, upper) {
  let res = [];
  let next = lower;
  for (let i = 0; i < nums.length; i++) {
    if (nums[i] < next) continue;
    if (nums[i] === next) {
      next++;
    } else {
      res.push([next, nums[i] - 1]);
      next = nums[i] + 1;
    }
  }
  if (next <= upper) res.push([next, upper]);
  return res;
}
